{
  "items": [
    {
      "name": "Polynomial.sum_eq_of_subset",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {S : Type u_1} [inst_1 : AddCommMonoid S] {p : Polynomial R} (f : ℕ → R → S),\n  (∀ (i : ℕ), f i 0 = 0) → ∀ {s : Finset ℕ}, p.support ⊆ s → p.sum f = ∑ n ∈ s, f n (p.coeff n)"
    },
    {
      "name": "FirstOrder.Ring.mvPolynomialSupportLEEquiv",
      "module_name": "Mathlib.RingTheory.MvPolynomial.FreeCommRing",
      "kind": "definition",
      "type": "{ι : Type u_1} →\n  {κ : Type u_2} →\n    {R : Type u_3} →\n      [DecidableEq κ] →\n        [inst : CommRing R] →\n          [DecidableEq R] →\n            (monoms : ι → Finset (κ →₀ ℕ)) → { p // ∀ (i : ι), (p i).support ⊆ monoms i } ≃ ((i : ι) × ↥(monoms i) → R)"
    },
    {
      "name": "MvPolynomial.coeffs",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → Finset R"
    },
    {
      "name": "Polynomial.finset_sum_coeff",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {ι : Type u_1} (s : Finset ι) (f : ι → Polynomial R) (n : ℕ),\n  (∑ b ∈ s, f b).coeff n = ∑ b ∈ s, (f b).coeff n"
    },
    {
      "name": "MvPolynomial.sum_def",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {A : Type u_2} [inst_1 : AddCommMonoid A] {p : MvPolynomial σ R}\n  {b : (σ →₀ ℕ) → R → A}, Finsupp.sum p b = ∑ m ∈ p.support, b m (MvPolynomial.coeff m p)"
    },
    {
      "name": "Polynomial.sum_def",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {S : Type u_1} [inst_1 : AddCommMonoid S] (p : Polynomial R) (f : ℕ → R → S),\n  p.sum f = ∑ n ∈ p.support, f n (p.coeff n)"
    },
    {
      "name": "Polynomial.sum",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Semiring R] → {S : Type u_1} → [AddCommMonoid S] → Polynomial R → (ℕ → R → S) → S"
    },
    {
      "name": "Polynomial.sum_over_range",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : AddCommMonoid S] (p : Polynomial R) {f : ℕ → R → S},\n  (∀ (n : ℕ), f n 0 = 0) → p.sum f = ∑ a ∈ Finset.range (p.natDegree + 1), f a (p.coeff a)"
    }
  ]
}
